ALL_METHODS = L4_METHODS + L7_METHODS

def is_l4(m: str) -> bool:
    return m.upper().replace("_","-") in L4_METHODS

def is_l7(m: str) -> bool:
    return m.upper().replace("_","-") in L7_METHODS

def normalize(m: str) -> str:
    return m.upper().replace("_","-").strip()


def method_info(name: str) -> dict:
    n = normalize(name)
    layer = "L4" if n in L4_METHODS else ("L7" if n in L7_METHODS else "unknown")
    return {"name": n, "layer": layer, "supported": layer != "unknown"}
